   144	        File configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
   145	        Path configuredStorePath = configuredFolder.toPath().toAbsolutePath().normalize();
   146	        Path configuredStoredRulesPath = configuredStorePath.resolve(STORED_RULES_FILE_NAME);
   147	        String configuredStorePathKey = canonicalPath(configuredStoredRulesPath);
   148	        Object configuredStoreLock = STORE_LOCKS_BY_PATH.computeIfAbsent(configuredStorePathKey, ignored -> new Object());
   149	
   150	        synchronized (configuredStoreLock) {
   151	            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), configuredStoredRulesPath);
   152	            boolean indexExists = Files.exists(configuredStoredRulesPath, java.nio.file.LinkOption.NOFOLLOW_LINKS);
   153	            if (!indexExists && !configuredStoreCreationAllowed) {
   154	                throw new StoreInitializationFailedException(String.format(
   155	                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
   156	                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
   157	            }
   158	
   159	            validateFolderAndIndex(configuredStorePath, configuredStoredRulesPath, indexExists);
   160	
   161	            IndexData index;
   162	            FileSyncedProperties sharedRules = STORED_RULES_BY_PATH.get(configuredStorePathKey);
   163	            if (indexExists) {
   164	                if (sharedRules == null) {
   165	                    sharedRules = loadStoredRules(configuredStoredRulesPath);
   166	                    STORED_RULES_BY_PATH.put(configuredStorePathKey, sharedRules);
   167	                } else {
   168	                    sharedRules.reload();
   169	                }
   170	                index = sharedRules.snapshot();
   171	            } else {
   172	                index = new IndexData();
   173	            }
   174	
   175	            if (configuredIntegrityMode != IntegrityMode.IGNORE) {
   176	                IntegrityAnalysis analysis = analyze(configuredStorePath, configuredStoredRulesPath, index,
   177	                        configuredStrategy, configuredRandomFileNames);
   178	                if (configuredIntegrityMode == IntegrityMode.FAIL && !analysis.isConsistent()) {
   179	                    throw new StoreInitializationFailedException(analysis.failureMessage(configuredStorePath));
   180	                }
   181	                if (configuredIntegrityMode == IntegrityMode.REPAIR) {
   182	                    repair(configuredStorePath, configuredStoredRulesPath, index, analysis);
   183	                    if (sharedRules != null && analysis.indexChanged) {
   184	                        sharedRules.replace(index);
   185	                    }
   186	                }
   187	            }
   188	
   189	            if (!indexExists) {
   190	                createFolder(configuredStorePath);
   191	                createIndex(configuredStoredRulesPath);
   192	                sharedRules = loadStoredRules(configuredStoredRulesPath);
   193	                if (!index.isEmpty()) {
   194	                    sharedRules.replace(index);
   195	                }
   196	                STORED_RULES_BY_PATH.put(configuredStorePathKey, sharedRules);
   197	            }
   198	
   199	            storeCreationAllowed = configuredStoreCreationAllowed;
   200	            storeUpdateAllowed = configuredStoreUpdateAllowed;
   201	            integrityMode = configuredIntegrityMode;
   202	            storeFolder = configuredFolder;
   203	            storePath = configuredStorePath;
   204	            storedRulesPath = configuredStoredRulesPath;
   205	            storeLock = configuredStoreLock;
   206	            storedRules = sharedRules != null ? sharedRules : STORED_RULES_BY_PATH.get(configuredStorePathKey);
   207	            activeStrategy = configuredStrategy;
