   319	    private IntegrityAnalysis analyze(Path folder, Path indexPath, IndexData index,
   320	            RuleViolationFileNameStrategy strategy, boolean randomNames) {
   321	        IntegrityAnalysis result = new IntegrityAnalysis(index.entries);
   322	        Path folderReal = realPathIfPossible(folder);
   323	        for (IndexEntry entry : index.entries) {
   324	            entry.derivedName = randomNames ? entry.fileName : createFileName(strategy, entry.ruleDescription);
   325	            entry.path = pathInfo(folder, indexPath, folderReal, entry.fileName);
   326	            entry.broken = entry.path.broken;
   327	            if (!entry.broken && isOnlyLineBreaks(entry.path.resolvedPath)) {
   328	                entry.resolved = true;
   329	            }
   330	            entry.misplaced = !entry.fileName.equals(entry.derivedName);
   331	        }
   332	
   333	        markSharedEntries(result.entries);
   334	        Map<String, List<IndexEntry>> collisions = groupByDerivedName(result.entries);
   335	        for (List<IndexEntry> colliding : collisions.values()) {
   336	            if (colliding.size() > 1) {
   337	                result.colliding.addAll(colliding);
   338	            }
   339	        }
   340	        for (IndexEntry entry : result.entries) {
   341	            if (entry.misplaced) {
   342	                entry.occupied = derivedNameIsOccupied(folder, indexPath, folderReal, result.entries, entry);
   343	            }
   344	            if (entry.broken) {
   345	                result.broken.add(entry);
   346	            }
   347	            if (entry.resolved) {
   348	                result.resolved.add(entry);
   349	            }
   350	            if (entry.shared) {
   351	                result.shared.add(entry);
   352	            }
   353	            if (entry.misplaced) {
   354	                result.misplaced.add(entry);
   355	            }
   356	            if (entry.occupied) {
   357	                result.occupied.add(entry);
   358	            }
   359	        }
   360	        result.unownedFiles.addAll(findUnownedFiles(folder, indexPath, result.entries));
   361	        return result;
   362	    }
