   373	    private static String descriptionFileName(String description) {
   374	        String normalized = ensureUnixLineBreaks(description);
   375	        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalized);
   376	        String keptWord = null;
   377	        while (matcher.find()) {
   378	            keptWord = matcher.group(1);
   379	        }
   380	        if (keptWord == null) {
   381	            keptWord = "rule";
   382	        }
   383	        return keptWord + "-" + sha256(normalized);
   384	    }
   385	
   386	    private static String sha256(String value) {
   387	        try {
   388	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
   389	            StringBuilder result = new StringBuilder(digest.length * 2);
   390	            for (byte part : digest) {
   391	                result.append(String.format("%02x", part & 0xff));
   392	            }
   393	            return result.toString();
   394	        } catch (NoSuchAlgorithmException e) {
   395	            throw new AssertionError(e);
   396	        }
   397	    }
