   399	    private void markSharedEntries(List<IndexEntry> entries) {
   400	        Map<String, List<IndexEntry>> sameNames = new HashMap<>();
   401	        for (IndexEntry entry : entries) {
   402	            sameNames.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
   403	        }
   404	        for (List<IndexEntry> sameName : sameNames.values()) {
   405	            if (sameName.size() > 1) {
   406	                for (IndexEntry entry : sameName) {
   407	                    entry.shared = true;
   408	                }
   409	            }
   410	        }
   411	        for (int i = 0; i < entries.size(); i++) {
   412	            for (int j = i + 1; j < entries.size(); j++) {
   413	                if (sameFile(entries.get(i).path.resolvedPath, entries.get(j).path.resolvedPath)) {
   414	                    entries.get(i).shared = true;
   415	                    entries.get(j).shared = true;
   416	                }
   417	            }
   418	        }
   419	    }
