   514	    private void repair(Path folder, Path indexPath, IndexData index, IntegrityAnalysis analysis) {
   515	        for (IndexEntry entry : new ArrayList<>(analysis.entries)) {
   516	            if (entry.shared) {
   517	                continue;
   518	            }
   519	            if (entry.broken || entry.resolved) {
   520	                if (entry.resolved && !entry.path.index && entry.path.resolvedPath != null) {
   521	                    deletePath(entry.path.resolvedPath, true);
   522	                }
   523	                index.remove(entry);
   524	                analysis.indexChanged = true;
   525	            } else if (entry.misplaced && !entry.occupied && !analysis.colliding.contains(entry)) {
   526	                movePath(entry.path.resolvedPath, pathInfo(folder, indexPath, realPathIfPossible(folder), entry.derivedName).path);
   527	                entry.fileName = entry.derivedName;
   528	                index.replace(entry);
   529	                analysis.indexChanged = true;
   530	            }
   531	        }
   532	    }
