   563	    @Override
   564	    public void save(ArchRule rule, List<String> violations) {
   565	        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
   566	        if (!storeUpdateAllowed) {
   567	            throw new StoreUpdateFailedException(String.format(
   568	                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
   569	                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
   570	        }
   571	        synchronized (storeLock) {
   572	            IndexEntry existing = storedRules.find(rule.getDescription());
   573	            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
   574	                if (existing != null) {
   575	                    forget(existing);
   576	                }
   577	                return;
   578	            }
   579	
   580	            String candidateFileName = createFileName(activeStrategy, rule.getDescription());
   581	            String fileName = existing == null ? candidateFileName : existing.fileName;
   582	            PathInfo target = pathInfo(storePath, storedRulesPath, realPathIfPossible(storePath), fileName);
   583	            validateSaveTarget(target, existing == null, fileName);
   584	
   585	            if (existing == null) {
   586	                if (storedRules.hasFileName(fileName)) {
   587	                    throw new StoreUpdateFailedException(String.format(
   588	                            "Cannot store rule '%s': violation file name '%s' is already recorded by another rule",
   589	                            rule.getDescription(), fileName));
   590	                }
   591	                write(violations, target.path);
   592	                try {
   593	                    storedRules.add(ensureUnixLineBreaks(rule.getDescription()), fileName);
   594	                } catch (RuntimeException e) {
   595	                    deletePath(target.path, false);
   596	                    throw e;
   597	                }
   598	            } else {
   599	                write(violations, target.path);
   600	            }
   601	        }
   602	    }
