   604	    private void validateSaveTarget(PathInfo target, boolean newEntry, String fileName) {
   605	        if (target.invalid || target.index || !target.canBeDirectFileName
   606	                || (target.existsWithoutFollowingLinks && !target.direct)
   607	                || (Files.isSymbolicLink(target.path) && target.resolvedPath == null)) {
   608	            throw new StoreUpdateFailedException(String.format(
   609	                    "Cannot store violations in '%s': the name does not lead directly into the violation store folder",
   610	                    fileName));
   611	        }
   612	        if (newEntry && target.existsWithoutFollowingLinks) {
   613	            throw new StoreUpdateFailedException(String.format(
   614	                    "Cannot store violations in '%s': the name is already occupied", fileName));
   615	        }
   616	    }
